121: function speakText(text) {
122:   if (!('speechSynthesis' in window) || !('SpeechSynthesisUtterance' in window)) {
123:     showToast('当前浏览器不支持语音朗读');
124:     return;
125:   }
126:   window.speechSynthesis.cancel();
127:   const utterance = new SpeechSynthesisUtterance(text);
128:   utterance.lang = 'zh-CN';
129:   utterance.rate = 0.96;
130:   const chineseVoice = window.speechSynthesis.getVoices().find((voice) => voice.lang.toLowerCase().startsWith('zh'));
131:   if (chineseVoice) utterance.voice = chineseVoice;
132:   utterance.onstart = () => { voiceSpeaking = true; updateAvatarActivity(); };
133:   utterance.onend = () => { voiceSpeaking = false; updateAvatarActivity(); };
134:   utterance.onerror = () => { voiceSpeaking = false; updateAvatarActivity(); };
135:   window.speechSynthesis.speak(utterance);
136: }
